mapper.select:
/* Attd06Mapper.selectShiftTeamUserInfos */ WITH RECURSIVE node_tree AS ( /* 로그인 사용자의 node 부터 시작 */ SELECT N.CMPNY_CD , N.SITE_CD , N.NODE_CD , N.NODE_NM FROM TB_SITE_NODE N WHERE N.CMPNY_CD = #{gvCmpnyCd} AND N.SITE_CD = #{siteCd}
AND N.NODE_CD = 'n1'
AND N.NODE_CD = #{nodeCd}
UNION ALL
/* 하위 노드 무한 확장 */ SELECT C.CMPNY_CD , C.SITE_CD , C.NODE_CD , C.NODE_NM FROM TB_SITE_NODE C INNER JOIN node_tree P ON C.CMPNY_CD = P.CMPNY_CD AND C.SITE_CD = P.SITE_CD AND C.PARENT_NODE_CD = P.NODE_CD )
SELECT A.CMPNY_CD AS cmpnyCd , A.SITE_CD AS siteCd , A.SHIFT_CD AS shiftCd , FNC_CMM_INFO_SRCH( A.CMPNY_CD , 'SHIFT_NO' , A.SITE_CD , A.SHIFT_CD ) AS shiftNm , A.SHIFT_TEAM_ID AS shiftTeamId , A.SHIFT_TEAM_NM AS shiftTeamNm , A.TEAM_IDX AS teamIdx , A.TEAM_NM AS teamNm , B.USER_CD AS userCd , B.USER_NM AS userNm , B.NODE_CD AS nodeCd , B.NODE_NM AS nodeNm , CASE WHEN B.NODE_CD = C.NODE_CD THEN 'Y' ELSE 'N' END editableYn , B.LEADER_YN AS leaderYn , A.STR_DATE AS strDate , A.END_DATE AS endDate FROM ( SELECT A.CMPNY_CD , A.SITE_CD , A.SHIFT_CD , A.SHIFT_TEAM_ID , A.SHIFT_TEAM_NM , B.TEAM_IDX , B.TEAM_NM , A.STR_DATE , A.END_DATE FROM TB_SHIFT_SCH_TEAM_MGMT A INNER JOIN TB_SHIFT_SCH_TEAM_META_INFO B ON ( A.CMPNY_CD = B.CMPNY_CD AND A.SITE_CD = B.SITE_CD AND A.SHIFT_CD = B.SHIFT_CD ) ) A LEFT OUTER JOIN ( SELECT A.CMPNY_CD , A.SITE_CD , A.SHIFT_CD , A.SHIFT_TEAM_ID , A.TEAM_IDX , C.TEAM_NM , A.USER_CD , B.USER_NM , B.NODE_CD , B.NODE_NM , A.LEADER_YN FROM TB_SHIFT_SCH_TEAM_USER A INNER JOIN ( SELECT A.CMPNY_CD , A.USER_CD , A.USER_NM , A.SITE_CD , A.NODE_CD , B.NODE_NM FROM TB_USER A LEFT OUTER JOIN TB_SITE_NODE B ON ( A.CMPNY_CD = B.CMPNY_CD AND A.SITE_CD = B.SITE_CD AND A.NODE_CD = B.NODE_CD ) WHERE A.CMPNY_CD = #{gvCmpnyCd} AND A.SITE_CD = #{siteCd}
) B ON ( A.CMPNY_CD = B.CMPNY_CD AND A.SITE_CD = B.SITE_CD AND A.USER_CD = B.USER_CD ) INNER JOIN TB_SHIFT_SCH_TEAM_META_INFO C ON ( A.CMPNY_CD = C.CMPNY_CD AND A.SITE_CD = C.SITE_CD AND A.SHIFT_CD = C.SHIFT_CD AND A.TEAM_IDX = C.TEAM_IDX ) WHERE A.CMPNY_CD = #{gvCmpnyCd} AND A.SITE_CD = #{siteCd} ) B ON ( A.CMPNY_CD = B.CMPNY_CD AND A.SITE_CD = B.SITE_CD AND A.SHIFT_CD = B.SHIFT_CD AND A.SHIFT_TEAM_ID = B.SHIFT_TEAM_ID AND A.TEAM_IDX = B.TEAM_IDX ) LEFT OUTER JOIN node_tree C ON ( A.CMPNY_CD = C.CMPNY_CD AND A.SITE_CD = C.SITE_CD AND B.NODE_CD = C.NODE_CD ) WHERE A.CMPNY_CD = #{gvCmpnyCd} AND A.SITE_CD = #{siteCd}

/* Attd06Mapper.selectUserLists */ WITH RECURSIVE node_tree AS ( /* 로그인 사용자의 node 부터 시작 */ SELECT N.CMPNY_CD , N.SITE_CD , N.NODE_CD , N.NODE_NM FROM TB_SITE_NODE N WHERE N.CMPNY_CD = #{gvCmpnyCd} AND N.SITE_CD = #{siteCd}
AND N.NODE_CD = #{nodeCd}
UNION ALL
/* 하위 노드 무한 확장 */ SELECT C.CMPNY_CD , C.SITE_CD , C.NODE_CD , C.NODE_NM FROM TB_SITE_NODE C INNER JOIN node_tree P ON C.CMPNY_CD = P.CMPNY_CD AND C.SITE_CD = P.SITE_CD AND C.PARENT_NODE_CD = P.NODE_CD ) SELECT A.USER_CD AS userCd , A.USER_ID AS userId , A.USER_NM AS usernm , A.NODE_CD AS nodeCd , B.NODE_NM AS nodeNm FROM TB_USER A INNER JOIN TB_SITE_NODE B ON ( A.CMPNY_CD = B.CMPNY_CD AND A.SITE_CD = B.SITE_CD AND A.NODE_CD = B.NODE_CD ) WHERE A.CMPNY_CD = #{gvCmpnyCd} AND A.SITE_CD = #{siteCd} AND A.USE_YN = 'Y' AND A.ACCOUNT_STATUS != '03'
AND A.NODE_CD = #{nodeCd}
AND NOT EXISTS ( SELECT 1 FROM TB_SHIFT_SCH_TEAM_USER STU WHERE STU.CMPNY_CD = A.CMPNY_CD AND STU.SITE_CD = A.SITE_CD AND STU.USER_CD = A.USER_CD )

/* Attd06Mapper.selectShiftTeamCd */
SELECT CONCAT(DATE_FORMAT(NOW(), '%Y%m'), FNC_CMM_SEQ_NEXTVAL(#{gvCmpnyCd}, 'TEAM_SHIFT_ID')) AS teamShiftId
FROM DUAL

mapper.update:
	/* Attd06Mapper.insertShiftTeam */
		INSERT INTO TB_SHIFT_SCH_TEAM_MGMT (
			CMPNY_CD
			, SITE_CD
			, SHIFT_CD
			, SHIFT_TEAM_ID
			, SHIFT_TEAM_NM
			, STR_DATE
			, END_DATE
			, INSERT_NO
			, INSERT_DATE
			, UPDATE_NO
			, UPDATE_DATE
		)
		VALUES
		(
			#{gvCmpnyCd}
	        , #{siteCd}
	        , #{shiftCd}
          	, #{shiftTeamId}
          	, IFNULL(NULLIF(#{shiftTeamNm}, ''), #{shiftTeamId})
          	, #{startDate}
          	, #{endDate}
          	, #{gvUserCd}
	        , NOW()
	        , #{gvUserCd}
	        , NOW()
		)

/* Attd06Mapper.insertShiftTeamUser */
	INSERT INTO TB_SHIFT_SCH_TEAM_USER (
	      CMPNY_CD
	    , SITE_CD
	    , SHIFT_CD
	    , SHIFT_TEAM_ID
	    , TEAM_IDX
	    , USER_CD
	    , LEADER_YN
	    , INSERT_NO
	    , INSERT_DATE
	    , UPDATE_NO
	    , UPDATE_DATE
	) VALUES

	    (
	        #{gvCmpnyCd}
	        , #{siteCd}
	        , #{shiftCd}
          	, #{shiftTeamId}
	        , #{teamIdx}
	        , #{member.userCd}
	        , #{member.leaderYn}
	        , #{gvUserCd}
	        , NOW()
	        , #{gvUserCd}
	        , NOW()
	    )

	AS NEW
	ON DUPLICATE KEY UPDATE
	    LEADER_YN   = NEW.LEADER_YN
	    , UPDATE_NO   = NEW.INSERT_NO
	    , UPDATE_DATE = NOW()

/* Attd06Mapper.updateShiftTeamNm */
UPDATE TB_SHIFT_SCH_TEAM_MGMT
SET 
	SHIFT_TEAM_NM = #{shiftTeamNm}
	, UPDATE_NO = #{gvUserCd}
	, UPDATE_DATE = NOW()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND SITE_CD = #{siteCd}
  AND SHIFT_TEAM_ID = #{shiftTeamId}

/* Attd06Mapper.deleteShiftTeamUser */
DELETE FROM TB_SHIFT_SCH_TEAM_USER
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND SITE_CD = #{siteCd}
  AND SHIFT_TEAM_ID = #{shiftTeamId}
  AND USER_CD = #{userCd}

    /* Attd06Mapper.insertShiftTeamUsers */
    INSERT INTO TB_SHIFT_SCH_TEAM_USER
    (
		CMPNY_CD
		, SITE_CD
		, SHIFT_CD
		, SHIFT_TEAM_ID
		, TEAM_IDX
		, USER_CD
		, LEADER_YN
		, INSERT_NO
		, INSERT_DATE
		, UPDATE_NO
		, UPDATE_DATE
	)
	VALUES
	(
		#{gvCmpnyCd}
		, #{siteCd}
		, #{shiftCd}
		, #{shiftTeamId}
		, #{teamIdx}
		, #{userCd}
		, 'N'
		, #{gvUserCd}
		, NOW()
		, #{gvUserCd}
		, NOW()
	)

    /* Attd06Mapper.updateShiftTeamLeaders */
    UPDATE TB_SHIFT_SCH_TEAM_USER
    SET LEADER_YN = #{leaderYn}
    	, UPDATE_NO = #{gvUserCd}
    	, UPDATE_DATE = NOW()
	WHERE CMPNY_CD = #{gvCmpnyCd}
	  AND SITE_CD = #{siteCd}
	  AND USER_CD = #{userCd}

/* Attd06Mapper.updateShiftTeamPeriod */
UPDATE TB_SHIFT_SCH_TEAM_MGMT
SET STR_DATE = #{strDate}
	, END_DATE = #{endDate}
	, UPDATE_NO = #{gvUserCd}
	, UPDATE_DATE = NOW() 
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND SITE_CD = #{siteCd}
  AND SHIFT_CD = #{shiftCd}
  AND SHIFT_TEAM_ID = #{shiftTeamId}

