mapper.insert:
/* Attd06Mapper.upsertUserWorkPlanList */
INSERT INTO TB_USER_WORK_PLAN (
    CMPNY_CD
    , SITE_CD
    , USER_CD
    , WORK_YMD
    , WORK_PLAN_CD
    , INSERT_NO
    , INSERT_DATE
) VALUES

    (
        #{item.cmpnyCd}
        , #{item.siteCd}
        , #{item.userCd}
        , #{item.workYmd}
        , #{item.schCd}
        , #{item.gvUserCd}
        , NOW()
    )

AS NEW
ON DUPLICATE KEY UPDATE
    WORK_PLAN_CD = NEW.WORK_PLAN_CD
    , UPDATE_NO = NEW.INSERT_NO
    , UPDATE_DATE = NOW()
